} from '../__tests__/menu-ui-fixtures.js'
import { fillSentinel, pixel, SENTINEL } from '../__tests__/raster-fixtures.js'
import { cloneInputs } from '../__tests__/render-input-snapshots.js'
import { createFramebuffer } from '../framebuffer.js'
import { drawInGameMagicMenu } from './draw-magic.js'

const glyphs = fixtureGlyphs()
const FACE_4 = 0xa4

afterEach(() => {
  resetHostSingletons()
})

function withoutFrame(index: number): IndexedImage[] {
  const source = makeUiFrames()
  const frames: IndexedImage[] = []
  for (let i = 0; i < source.length; i++) {
    if (i !== index) frames[i] = source[i]!
  }
  return frames
}

function makeMagic(id: number, costMP: number): Magic {
  return {
    id,
    effect: 0,
    type: 'applyToPlayer',
    xOffset: 0,
    yOffset: 0,
    special: 0,
    speed: 0,
    keepEffect: 0,
    fireDelay: 0,
    effectTimes: 0,
    shake: 0,
    wave: 0,
    unknown: 0,
    costMP,
    baseDamage: 0,
    elemental: 0,
    sound: 0,
  }
}

function makeSpell(id: number, name: string, magicNumber: number, scriptDesc = 0): Spell {
  return {
    id,
    _name: name,
    magicNumber,
    scriptOnSuccess: 0,
    scriptOnUse: 0,
    scriptDesc,
    flags: {
      usableOutsideBattle: true,
      usableInBattle: true,
      usableToEnemy: false,
      applyToAll: false,
    },
  }
}

function casterState(party: number[]): InGameMagicMenuState {
  return {
    phase: 'pick-caster',
    casterMenu: {
      items: party.map((id) => ({ id, label: '甲', disabled: false })),
      cursor: 0,
      pageSize: 4,
      pageOffset: 0,
    },
    targetCursor: 0,
    partyMembers: [...party],
  }
}

function spellState(
  party: number[],
  spells: Spell[],
  casterId: number | undefined,
): InGameMagicMenuState {
  return {
    phase: 'pick-spell',
    casterMenu: {
      items: party.map((id) => ({ id, label: '甲', disabled: false })),
      cursor: 0,
      pageSize: 4,
      pageOffset: 0,
