  MENUITEM_COLOR_SELECTED_FIRST,
} from '../../../core/menu/inventory-menu.js'
import { createFramebuffer } from '../../framebuffer.js'
import { drawInGameMagicMenu } from '../../menu/draw-magic.js'
import { fixtureGlyphs, textDot } from '../glyph-fixtures.js'
import { freezeNow, makeGs, makeRoles, resetHostSingletons } from '../menu-state-fixtures.js'
import {
  CURSOR_UP_ID,
  cyanDigit,
  makeUiFrames,
  rightDigitX,
  yellowDigit,
} from '../menu-ui-fixtures.js'
import { fillSentinel, pixel, SENTINEL } from '../raster-fixtures.js'
import { cloneInputs } from '../render-input-snapshots.js'

const glyphs = fixtureGlyphs()
const NAMES = [...'甲乙丙丁戊己庚辛壬癸子丑寅卯辰巳']

afterEach(() => {
  resetHostSingletons()
})

function makeMagic(id: number, costMP: number): Magic {
  return {
    id,
    effect: 0,
    type: 'applyToPlayer',
    xOffset: 0,
    yOffset: 0,
    special: 0,
    speed: 0,
    keepEffect: 0,
    fireDelay: 0,
    effectTimes: 0,
    shake: 0,
    wave: 0,
    unknown: 0,
    costMP,
    baseDamage: 0,
    elemental: 0,
    sound: 0,
  }
}

/** 正式菜单先把 runtime 投影成 roles。静态 mp/magic 不再单独驱动 disabled。 */
function viewRuntime(
  gs: GameState,
  staticRoles: PlayerRoles,
  roleId: number,
  spellIds: number[],
  mp: number,
): PlayerRoles {
  gs.PlayerRolesRuntime.rgwMP[roleId] = mp
  spellIds.forEach((id, slot) => {
    gs.PlayerRolesRuntime.rgwMagic[slot]![roleId] = id
  })
  return projectRuntimeToBattleRoles(gs.PlayerRolesRuntime, staticRoles)
}

function makeSpell(id: number, name: string, magicNumber: number, scriptDesc = 0): Spell {
  return {
    id,
    _name: name,
    magicNumber,
    scriptOnSuccess: 0,
    scriptOnUse: 0,
    scriptDesc,
    flags: {
      usableOutsideBattle: true,
      usableInBattle: true,
      usableToEnemy: false,
      applyToAll: false,
    },
  }
}

