    const frames = makeUiFrames()
    const fb = createFramebuffer()
    fillSentinel(fb)
    const inputs = { gs, menu, items: [], roles: viewed, frames, spells, magics }
    const restore = freezeNow(0)
    try {
      const beforeFirst = cloneInputs(inputs)
      drawInGameMagicMenu({
        fb,
        state: menu,
        gs,
        playerRoles: viewed,
        spells,
        magics,
        uiSpriteFrames: frames,
