      fillSentinel(fb)
      const beforePage = cloneInputs(inputs)
      drawInGameMagicMenu({
        fb,
        state: menu,
        gs,
        playerRoles: viewed,
        spells,
        magics,
        uiSpriteFrames: frames,
        glyphs: positionGlyphs,
