    expect(menu.spellMenu?.items.map((entry) => entry.disabled)).toEqual([false, true])
    const frames = makeUiFrames()
    const fb = createFramebuffer()
    fillSentinel(fb)
    const inputs = { gs, menu, items: [], roles: viewed, frames, spells, magics }
